SELECT p.status, p.close_reason, COUNT(*) AS n, SUM(p.realized_pnl<0) AS losses, ROUND(SUM(p.realized_pnl),4) AS pnl_usdt, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_ret_pct, MIN(p.id) AS min_id, MAX(p.id) AS max_id, MIN(UNIX_TIMESTAMP(p.closed_at)) AS first_close_epoch, MAX(UNIX_TIMESTAMP(p.closed_at)) AS last_close_epoch, SUM(p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400)) AS n_14d FROM crypto_ai.paper_position p WHERE p.status IN ('CLOSED','STOPPED') GROUP BY p.status, p.close_reason ORDER BY p.status, n DESC LIMIT 40;